function damageBenchmark(s,target,move,evs){const atkStats=actualStats(s),base=master(target.name)?.slice(3,9).map(Number);if(!atkStats||!base)return null;const defStats=calculateStats(base,evs,null),type=koreanType[move[2]]||move[2],category=move[3],attack=category==='물리'?atkStats[1]:atkStats[3],defense=category==='물리'?defStats[2]:defStats[4],stab=row(s.name).types.includes(type)?(s.abilities==='적응력'?2:1.5):1,typeMult=multiplier(type,target.types),mod=stab*typeMult*itemPower(s.items,type,category)*abilityPower(s.abilities,type,category);return classifyKO(damageRolls(Number(move[4]),attack,defense,mod),defStats[0])}
