function renderAnalysis(){const ts=team().filter(Boolean);if(!ts.length){$('analysis').innerHTML='<p>첫 포켓몬을 추가하면 팀메이트 연결, 메타상 주의 상대와 투자 결과를 점검합니다.</p>';return}let pairs=[];for(let i=0;i<ts.length;i++)for(let j=i+1;j<ts.length;j++)if(row(ts[i].name).teammates.includes(ts[j].name)||row(ts[j].name).teammates.includes(ts[i].name))pairs.push(ts[i].name+' + '+ts[j].name);
let threats={};for(const s of ts)for(const c of row(s.name).counters){if(!threats[c.name])threats[c.name]=[];threats[c.name].push({target:s.name,...c})}let common=Object.entries(threats).sort((a,b)=>b[1].reduce((v,c)=>v+c.rate*Math.log10(c.n+1),0)-a[1].reduce((v,c)=>v+c.rate*Math.log10(c.n+1),0)).slice(0,4);
$('analysis').innerHTML=`<div class="analysisitem"><strong>팀메이트 연결 ${pairs.length}쌍</strong><p>${pairs.length?esc(pairs.join(', ')):'선택한 조합은 상위 팀메이트 목록에서 연결되지 않습니다. 이것만으로 조합의 성능을 판단할 수는 없습니다.'}</p></div><div class="analysisitem"><strong>실전 통계상 주의 상대</strong><p>원본의 ‘이 포켓몬을 쓰러뜨린 포켓몬’ 통계를 표본 수와 승률로 정렬했습니다.</p>${common.length?common.map(([n,cs])=>`<p><b>${esc(n)}</b> — ${cs.map(c=>esc(c.target)+' 상대 '+c.rate+'%, 표본 '+c.n).join(' / ')}</p>`).join(''):'<p>원본에 쓰러뜨린 포켓몬 통계가 없습니다.</p>'}</div>`+performanceHtml(ts)}
function renderTypeAnalysis(){const members=team().filter(Boolean),names=members.map(s=>s.name);if(!names.length)return;const rows=teamTypeSummary(stats(),names),gaps=rows.filter(r=>r.weak.length&&!r.resist.length);const targets=O?.modes[mode].frequency.slice(0,20)||[];let html=`<div class="analysisitem"><h3>타입 보완 점검</h3><p>기본 타입 기준입니다. 메가진화·특성·도구 효과와 실제 데미지는 반영하지 않아 승패를 확정하지 않습니다.</p><p>${gaps.length?'저항할 멤버가 없는 약점: '+esc(gaps.map(x=>x.type).join(', ')):'확인된 공통 약점마다 저항할 멤버가 있습니다.'}</p><div class="tablewrap"><table class="typetable"><thead><tr><th>상대 공격 타입</th><th>약점인 멤버</th><th>저항·무효 멤버</th></tr></thead><tbody>${rows.filter(r=>r.weak.length||r.resist.length).map(r=>`<tr><td>${esc(r.type)}</td><td class="${r.weak.length&&!r.resist.length?'warning-cell':''}">${esc(r.weak.join(', ')||'없음')}</td><td class="${r.resist.length?'good-cell':''}">${esc(r.resist.join(', ')||'없음')}</td></tr>`).join('')}</tbody></table></div></div><div class="analysisitem"><h3>상위 메타 20종 대응 점검</h3><p>M-4 공개 파티 표본 기준입니다. 내 선택 기술과 상대의 통계 상위 4개 기술을 비교합니다. 효과가 굉장한 공격이 있고 상대 공격을 1배 이하로 받는 경우를 타입상 대응 후보로 표시합니다.</p><div class="tablewrap"><table class="typetable"><thead><tr><th>상대 / 표본 내 채용</th><th>타입상 대응 후보</th><th>근거</th></tr></thead><tbody>${targets.map(t=>{const target=row(t.name);if(!target)return `<tr><td>${esc(t.name)}</td><td colspan="2">상세 통계 없음</td></tr>`;const answers=members.map(s=>({s,m:matchup(row(s.name),target,D.master,s)})).filter(x=>x.m.usable);return `<tr><td><button class="monlink" data-detail="${esc(t.name)}">${esc(t.name)}</button><small>${t.rate}%</small></td><td class="${answers.length?'good-cell':'warning-cell'}">${esc(answers.map(x=>x.s.name).join(', ')||'미확보')}</td><td>${answers.map(x=>esc(x.m.attack.name)+' ×'+x.m.attack.multiplier+' / 상대 공격 최대 ×'+x.m.incoming.multiplier).join('<br>')||'현재 선택 기술과 기본 타입으로 확인되는 대응 후보 없음'}</td></tr>`}).join('')}</tbody></table></div><p>추가 기술, 스피드, 내구, 선공기, 변화기 운영에 따라 실제 대면은 달라집니다.</p></div>`;$('analysis').insertAdjacentHTML('beforeend',html)}
function renderMeta(){const q=$('search').value.trim();const rows=stats().filter(p=>p.name.includes(q));$('metaCount').textContent=`${mode==='single'?'싱글':'더블'} ${stats().length}종 · 포켓몬 전체 사용률 수치는 원문에 없음`; $('metarows').innerHTML=rows.map(p=>`<tr><td>${p.rank}</td><td><div class="moncell">${monSprite(p.name,'medium')}<button class="monlink" data-detail="${esc(p.name)}">${esc(p.name)}</button></div></td><td>${esc(p.types.join(' / '))}</td><td>${field(p,'items')}</td><td>${field(p,'abilities')}</td><td><button data-detail="${esc(p.name)}">상세</button> <button data-add="${esc(p.name)}">추가</button></td></tr>`).join('')}
function picker(){const q=$('pickSearch').value.trim();$('pickList').innerHTML=stats().filter(p=>p.name.includes(q)).map(p=>`<button class="pickrow" data-select="${esc(p.name)}"><span class="moncell">${monSprite(p.name,'medium')}<span>${esc(p.name)} <small>${esc(p.types.join(' / '))}</small></span></span><small>${p.rank}위</small></button>`).join('')}
function opts(p,k,value){return '<option value="">선택 안 함</option>'+p[k].map(x=>`<option value="${esc(x.name)}" ${x.name===value?'selected':''}>${esc(x.name)} (${x.rate}%)</option>`).join('')}
function rankedChoices(p,k){const seen=new Set(),out=[];for(const x of p?.[k]||[]){seen.add(x.name);out.push({name:x.name,label:`${x.name} · 채용률 ${x.rate}%`})}for(const x of D.master[k]||[]){if(!seen.has(x[0]))out.push({name:x[0],label:`${x[0]} · 상세 통계 미등재`})}return out}
function searchChoice(p,k,id,value,label,attrs=''){const r=rate(p,k,value);return `<label>${label}<input id="${id}" ${attrs} type="search" list="${id}-list" value="${esc(value||'')}" placeholder="이름 검색 또는 직접 입력" autocomplete="off"><datalist id="${id}-list">${rankedChoices(p,k).map(x=>`<option value="${esc(x.name)}">${esc(x.label)}</option>`).join('')}</datalist><small>${value?(r!==undefined?'현재 채용률 '+r+'%':'챔피언스 전체 목록 · 이 포켓몬 통계 미등재'):'선택 안 함'}</small></label>`}
function edit(i,detailName){editing=i;const s=i<0?makeSet(row(detailName)):team()[i],p=row(s.name);$('editorTitle').textContent=s.name+' · '+p.rank+'위';$('editorBody').innerHTML=`<p>${esc(p.types.join(' / '))} · 종족값 ${master(p.name).slice(3,9).join(' / ')}<br>HP / 공격 / 방어 / 특공 / 특방 / 스피드</p><div class="formgrid">${[['items','도구'],['abilities','특성'],['natures','성격']].map(([k,l])=>searchChoice(p,k,'ed-'+k,s[k],l)).join('')}<label>통계 배분<select id="evChoice">${opts(p,'evs',evtext(s.evs))}</select><small>통계 배분 또는 아래에서 직접 입력</small></label></div><div class="statgrid">${'HABCDS'.split('').map((k,j)=>`<label>${k}<input type="number" min="0" max="32" step="1" id="ev-${j}" value="${s.evs[j]??0}"></label>`).join('')}</div><p id="evsum"></p><div class="formgrid">${[0,1,2,3].map(j=>searchChoice(p,'moves','move-'+j,s.moves[j],`기술 ${j+1}`)).join('')}</div><p>검색 후보는 이 포켓몬의 채용률순 통계를 먼저, 챔피언스 전체 마스터 목록을 그 뒤에 표시합니다. 상세 통계 미등재 기술·특성은 이 포켓몬이 사용할 수 있는지 현재 자료만으로 검증할 수 없으므로 직접 확인해야 합니다.</p>`;$('saveMember').hidden=false;$('saveMember').textContent=i<0?'내 파티에 적용':'세팅 저장';$('removeMember').hidden=i<0; $('evChoice').onchange=()=>{const vals=evparse($('evChoice').value);if(vals.length===6)vals.forEach((v,j)=>$('ev-'+j).value=v);evCheck()};for(let j=0;j<6;j++)$('ev-'+j).oninput=evCheck;evCheck();$('editor').showModal()}
function evCheck(){const v=Array.from({length:6},(_,j)=>Number($('ev-'+j).value));$('evsum').textContent=evtext(v)+' (합계 '+sum(v)+(validEV(v)?' ✓)': ' · 범위 초과)')}
$('saveMember').onclick=()=>{const name=editing<0?$('editorTitle').textContent.split(' · ')[0]:team()[editing].name,s={name,items:$('ed-items').value.trim(),abilities:$('ed-abilities').value.trim(),natures:$('ed-natures').value.trim(),moves:[0,1,2,3].map(j=>$('move-'+j).value.trim()).filter(Boolean),evs:Array.from({length:6},(_,j)=>Number($('ev-'+j).value))};if(!validSet(s))return toast('챔피언스 전체 목록의 정확한 공식 한글 명칭, 배분 범위와 기술 중복을 확인해 주세요.');let target=editing;if(target<0)target=team().findIndex(x=>x?.name===name);if(target<0)target=team().indexOf(null);if(target<0)return toast('파티가 가득 찼습니다. 먼저 한 자리를 비워 주세요.');if(team().some((x,j)=>j!==target&&x?.name===name))return toast('동일한 포켓몬이 이미 파티에 있습니다.');team()[target]=s;persist();render();$('editor').close();$('details').close();toast(`${name} 세팅을 파티에 적용했습니다.`)};
$('removeMember').onclick=()=>{team()[editing]=null;persist();render();$('editor').close()};
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.tab){document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x===b));['builder','meta','import','ranked','lead','calculators'].forEach(t=>$(t).hidden=t!==b.dataset.tab)}if(b.dataset.close)$(b.dataset.close).close();if(b.dataset.pick!==undefined){slot=+b.dataset.pick;$('pickSearch').value='';picker();$('picker').showModal()}if(b.dataset.select){add(b.dataset.select,slot);$('picker').close()}if(b.dataset.add)add(b.dataset.add);if(b.dataset.edit!==undefined)edit(+b.dataset.edit);if(b.dataset.detail)showDetails(b.dataset.detail)});
for(const m of ['single','double'])$(m).onclick=()=>{mode=m;spriteFeaturePromise=null;['single','double'].forEach(k=>$(k).classList.toggle('active',k===m));ocr=Array.from({length:6},()=>({name:'',items:'',abilities:'',natures:'',moves:[],evs:Array(6).fill(null),raw:''}));renderOcr();render()};$('search').oninput=renderMeta;$('pickSearch').oninput=picker;
$('fill').onclick=()=>{if(!team().includes(null))return toast('이미 여섯 자리가 채워져 있습니다.');while(team().includes(null)){const c=candidates().find(({p})=>p.items.length&&p.abilities.length&&p.natures.length&&p.evs.length&&p.moves.length>=4);if(!c)break;add(c.p.name)}toast('타입 보완과 메타 대응 기준으로 채웠습니다. 세팅을 검토해 주세요.')};$('clear').onclick=()=>{if(confirm('현재 모드의 파티를 초기화할까요?')){teams[mode]=Array(6).fill(null);persist();render()}};
$('export').onclick=()=>{const b=new Blob([JSON.stringify({version:1,mode,date:D.date,team:team()},null,2)],{type:'application/json'});const u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='champions-party-'+mode+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),5000)};
$('jsonFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>1e6)throw Error();const v=JSON.parse(await f.text());if(v.mode!==mode)return toast('파일과 같은 배틀 모드로 전환해 주세요.');if(!Array.isArray(v.team)||v.team.length!==6||!v.team.every(s=>s===null||validSet(s)))throw Error();const names=v.team.filter(Boolean).map(s=>s.name);if(new Set(names).size!==names.length)throw Error();teams[mode]=v.team;persist();render();toast('파티를 불러왔습니다.')}catch{toast('파일 형식 또는 챔피언스 데이터 검증에 실패했습니다.')}finally{e.target.value=''}};
$('sourceBtn').onclick=()=>{$('sourceBody').innerHTML=`<p><b>현재 데이터: ${D.date} / ${D.season}</b></p><p>첨부 파일 원문 출처: ${esc(D.source)}. champs.pokedb.tokyo 오픈데이터 M-4를 별도로 연결했습니다. 공개 싱글 223개, 더블 31개 파티이며 원문 갱신일은 2026-08-19입니다. 상위 파티 데이터에는 상세 세팅이 없으므로 첨부 통계를 보완 자료로 씁니다. 두 표본을 합산해 사용률을 계산하지 않습니다.</p><p>마스터 목록: 포켓몬 ${D.master.pokemon.length}종, 도구 ${D.master.items.length}종, 기술 ${D.master.moves.length}종, 특성 ${D.master.abilities.length}종, 성격 ${D.master.natures.length}종.</p><p>싱글 ${D.modes.single.length}종, 더블 ${D.modes.double.length}종을 전체 파싱했습니다. 원문 일본어·숫자 식별자 등 검증을 통과하지 못한 항목 ${D.excludedCount}건을 추천에서 제외했습니다. 한국어 항목은 첨부 마스터 표기를 사용합니다. 오픈데이터의 일본어 이름과 폼은 명시적인 대응표를 거쳐 마스터 명칭으로 연결하며 목록 밖 항목은 수집을 중단합니다. 공식 명칭 전체에 대한 외부 대조는 아직 완료되지 않았습니다.</p><p>추천은 약점 보완 최대 30점, 미대응 상위 메타의 타입상 대응 최대 30점, 쓰러뜨린 포켓몬의 역방향 실전 대응 최대 25점, 팀메이트·공개 파티 동반 기록 최대 20점과 순위 보정으로 평가합니다. 파티 점검에서는 원본의 ‘이 포켓몬을 쓰러뜨린 포켓몬’ 항목을 승률과 표본 수로 정렬합니다. 공통 약점을 더 겹치게 만들면 감점합니다. 추천 점수는 예상 승률이 아닙니다.</p><p>능력 배분은 각 항목 0~32, 총합 66 이하로 검증합니다. OCR에서 읽지 못한 항목은 포켓몬 선택 후 해당 모드 최상위 통계 세팅으로 보완하며 화면에 그 사실을 표시합니다.</p><p><a href="https://op.gg/ko/pokemon-champions/type-effectiveness" target="_blank" rel="noreferrer">챔피언스 타입 상성표</a></p><p>사용한 파일: AI_지침.md, master_index.md, stats_single.md, stats_double.md. 포켓몬·세팅·메타에는 구작 데이터나 외부 포켓몬 API를 사용하지 않습니다. 포켓몬 표시용 도트와 보조 인식 이미지만 PokeAPI에서 폼별로 확인해 앱에 저장했습니다. 사용자 제공 챔피언스 화면에서 분리한 아이콘 특징은 별도 인식 DB로 관리합니다.</p>`;$('sources').showModal()};
function norm(s){return s.normalize('NFKC').replace(/\s/g,'')}
function matchText(text,k){const t=norm(text);return D.master[k].map(x=>x[0]).filter(n=>t.includes(norm(n))).sort((a,b)=>b.length-a.length).filter((n,i,a)=>!a.slice(0,i).some(long=>long.includes(n)))}
function parseAbility(text){const matched={};for(const k of ['pokemon','items','abilities','moves'])matched[k]=matchText(text,k);let exact=matched.pokemon.filter(n=>row(n));let scores=stats().map(p=>({p,score:['items','abilities','moves'].reduce((a,k)=>a+matched[k].filter(n=>p[k].some(x=>x.name===n)).length,0)})).filter(x=>x.score>=2).sort((a,b)=>b.score-a.score);return {matched,candidates:exact.length?exact:scores.slice(0,8).map(x=>x.p.name),name:exact.length===1?exact[0]:''}}
function renderOcr(){$('ocrResults').innerHTML=ocr.map((o,i)=>{const p=row(o.name);return `<div class="ocrrow"><div class="sectionhead"><h3>슬롯 ${i+1} · ${o.name?esc(o.name):'포켓몬 확인 필요'}</h3>${o.name?`<button data-detail="${esc(o.name)}">상세 통계</button><button data-ocrclear="${i}">선택 해제</button>`:''}</div><div class="candidates" aria-label="슬롯 ${i+1} 인식 후보">${(o.candidates||[]).map(n=>`<button class="candidate ${o.name===n?'chosen':''}" data-ocrcandidate="${i}" data-name="${esc(n)}" aria-pressed="${o.name===n}">${esc(n)}${o.name===n?' ✓':''}</button>`).join('')||'<p>확인된 후보가 없습니다. 이름으로 검색해 주세요.</p>'}</div><label class="ocrsearchlabel">포켓몬 검색<input type="search" data-ocrquery="${i}" placeholder="공식 한글 이름 입력" autocomplete="off" aria-label="슬롯 ${i+1} 포켓몬 검색"></label><div class="ocrmatches" data-ocrmatches="${i}" aria-live="polite"></div>${p?`<div class="ocrfields">${searchChoice(p,'items',`ocr-${i}-items`,o.items,'도구',`data-ocrfield="items" data-ocrslot="${i}"`)}${searchChoice(p,'abilities',`ocr-${i}-abilities`,o.abilities,'특성',`data-ocrfield="abilities" data-ocrslot="${i}"`)}${searchChoice(p,'natures',`ocr-${i}-natures`,o.natures,'성격',`data-ocrfield="natures" data-ocrslot="${i}"`)}${[0,1,2,3].map(j=>searchChoice(p,'moves',`ocr-${i}-move-${j}`,o.moves[j]||'',`기술 ${j+1}`,`data-ocrmove="${j}" data-ocrslot="${i}"`)).join('')}</div>`:'<p>포켓몬을 먼저 선택하면 도구·특성·성격·기술을 검색하거나 직접 입력할 수 있습니다.</p>'}${o.fallback?.length?`<p class="ocrfallback">통계 보완: ${esc(o.fallback.join(', '))} · 인식되지 않은 값은 해당 모드 최상위 채용 세팅을 사용했습니다.</p>`:''}<div class="statgrid">${'HABCDS'.split('').map((k,j)=>`<label>${k}<input type="number" min="0" max="32" step="1" data-ocrslot="${i}" data-ocrstat="${j}" value="${o.evs[j]??''}" placeholder="—"></label>`).join('')}</div><p data-ocrsum="${i}">합계 ${sum(o.evs)} / 66 ${o.evs.some(v=>v===null)?'· 미확인 값 있음':''}</p><details><summary>인식 원문 확인 / 수정</summary><textarea data-raw="${i}" aria-label="슬롯 ${i+1} 능력 인식 원문">${esc(o.raw)}</textarea>${o.statsRaw?'<p>스테이터스 인식 원문</p><pre style="white-space:pre-wrap;font-size:12px">'+esc(o.statsRaw)+'</pre>':''}<button data-reparse="${i}">수정 원문 다시 반영</button></details></div>`}).join('')}
