function subsetScore(group,opponents){const results=group.map(n=>leadMatch(n,opponents)),coverage=opponents.reduce((a,o)=>a+Math.max(...results.map(r=>r.duels.find(x=>x.name===o).score)),0),synergy=group.reduce((a,n,i)=>a+group.slice(i+1).filter(m=>row(n).teammates.includes(m)||row(m).teammates.includes(n)).length*6,0),gaps=teamTypeSummary(stats(),group).filter(x=>x.weak.length&&!x.resist.length).length;return {group,results,score:coverage+results.reduce((a,r)=>a+r.score,0)*.18+synergy-gaps*2}}
$('leadRecommend').onclick=()=>{const mine=lead.mine.map(x=>x.name),opponents=lead.opp.map(x=>x.name),count=mode==='single'?3:4;if(new Set(mine).size<6||new Set(opponents).size<6)return toast('양쪽 여섯 마리를 중복 없이 확인해 주세요.');const best=combination(mine,count).map(g=>subsetScore(g,opponents)).sort((a,b)=>b.score-a.score)[0];let order;if(mode==='double'){const pairs=combination(best.group,2).map(pair=>({pair,score:subsetScore(pair,opponents).score+(row(pair[0]).teammates.includes(pair[1])||row(pair[1]).teammates.includes(pair[0])?10:0)})).sort((a,b)=>b.score-a.score)[0].pair;order=[...pairs,...best.group.filter(n=>!pairs.includes(n)).sort((a,b)=>leadMatch(b,opponents).score-leadMatch(a,opponents).score)]}else order=[...best.group].sort((a,b)=>leadMatch(b,opponents).score-leadMatch(a,opponents).score);const labels=mode==='single'?['선봉','2번','3번']:['선봉 1','선봉 2','후발 1','후발 2'];$('leadResult').innerHTML=`<section class="leadrecommend"><h3>${mode==='single'?'싱글 3마리':'더블 4마리'} 추천</h3><div class="leadorder">${order.map((n,i)=>`<article><span>${labels[i]}</span>${monSprite(n,'large')}<button class="monlink" data-detail="${esc(n)}">${esc(n)}</button></article>`).join('')}</div>${order.map(n=>{const r=leadMatch(n,opponents),good=[...r.duels].sort((a,b)=>b.score-a.score).slice(0,2),bad=[...r.duels].sort((a,b)=>a.score-b.score)[0];return `<p><b>${esc(n)}</b> — 유리 후보 ${good.map(x=>`${esc(x.name)} (${esc(x.out.move)} ${x.out.minPct}~${x.out.maxPct}%, ${x.out.label})`).join(' · ')}<br><small>주의: ${esc(bad.name)}의 통계 상위 세팅 기준 최대 피해 ${bad.incoming.minPct}~${bad.incoming.maxPct}% · ${bad.incoming.label}</small></p>`}).join('')}<p class="leadnotice">선택한 내 세팅, 상대의 통계 최상위 세팅, 타입 상성·자속·기술 위력·공격/방어 실능력치·확인 가능한 도구/상시 특성 보정, 쓰러뜨린 상대와 팀메이트 통계를 함께 계산했습니다. 상대 실제 세팅과 교체·변화기 운영은 알 수 있으므로 최종 선택 전 후보를 확인하세요.</p></section>`;$('leadResult').scrollIntoView({behavior:'smooth',block:'nearest'})};
function renderRanked(){if(!O){$('rankedSummary').textContent='오픈데이터를 불러오지 못했습니다.';return}const d=O.modes[mode],q=$('rankedSearch').value.trim();$('rankedSummary').textContent=`${d.season} · 공개 파티 ${d.count}개 · 원문 갱신 ${d.updatedAt} (JST)`;$('openFrequency').innerHTML=d.frequency.slice(0,8).map((f,i)=>`<div class="freq"><span class="type">표본 내 ${i+1}위</span>${monSprite(f.name,'large')}<button class="monlink" data-detail="${esc(f.name)}">${esc(f.name)}</button><b>${f.rate}%</b><small>${f.count} / ${d.count}개 파티</small></div>`).join('');$('rankedTeams').innerHTML=d.teams.filter(t=>!q||t.team.some(m=>m.name.includes(q))).map(t=>`<article class="rankedteam"><div class="sectionhead"><h2>최종 ${t.rank}위 <span>레이팅 ${t.rating.toFixed(3)}</span></h2><button data-ranked="${t.rank}">파티로 가져오기</button></div><div class="rankedsix">${t.team.map(m=>`<div>${monSprite(m.name,'medium')}<button class="monlink" data-detail="${esc(m.name)}">${esc(m.name)}</button><small>${esc(m.item||'도구 없음')}</small></div>`).join('')}</div></article>`).join('')}
$('rankedSearch').oninput=renderRanked;
document.addEventListener('click',e=>{const b=e.target.closest('[data-ranked]');if(!b||!O)return;const t=O.modes[mode].teams.find(t=>t.rank===+b.dataset.ranked);if(team().some(Boolean)&&!confirm('현재 파티를 이 상위 파티로 교체할까요?'))return;let missing=[];let next=t.team.map(m=>{const p=row(m.name);if(!p){missing.push(m.name);return null}const s=makeSet(p);if(p.items.some(v=>v.name===m.item))s.items=m.item;else{s.items='';missing.push(m.name+' 도구')}return s});teams[mode]=next;persist();render();document.querySelector('[data-tab="builder"]').click();toast(missing.length?'가져왔습니다. 첨부 상세 통계에 없는 항목은 비워 두었습니다: '+missing.join(', '):'구성과 도구를 가져왔습니다. 나머지 세팅은 첨부 통계 기반 초안입니다.')});
function renderCalcNames(){$('calcMons').innerHTML=stats().map(p=>`<option value="${esc(p.name)}"></option>`).join('');if(!row($('calcAtk').value))$('calcAtk').value=team().find(Boolean)?.name||stats()[0].name;if(!row($('calcDef').value))$('calcDef').value=stats()[1].name;renderCalcMoves()}
function renderCalcMoves(){const p=row($('calcAtk').value.trim()),set=p?(team().find(x=>x?.name===p.name)||makeSet(p)):null,moves=(set?.moves||[]).map(n=>D.master.moves.find(x=>x[0]===n)).filter(m=>m&&m[3]!=='변화'&&Number(m[4])>0);$('calcMove').innerHTML=moves.map(m=>`<option value="${esc(m[0])}">${esc(m[0])} · ${esc(koreanType[m[2]]||m[2])} · 위력 ${m[4]}</option>`).join('')||'<option value="">공격 기술 없음</option>'}
function runCalculator(){const attacker=row($('calcAtk').value.trim()),defender=row($('calcDef').value.trim()),move=D.master.moves.find(x=>x[0]===$('calcMove').value);if(!attacker||!defender||!move)return toast('현재 챔피언스 목록의 포켓몬과 공격 기술을 선택해 주세요.');const set=team().find(x=>x?.name===attacker.name)||makeSet(attacker),evs=$('calcBulk').value.split(',').map(Number),result=damageBenchmark(set,defender,move,evs),a=actualStats(set),zero=actualStats(set,[0,0,0,0,0,0]),type=koreanType[move[2]]||move[2],stab=attacker.types.includes(type)?(set.abilities==='적응력'?2:1.5):1,power=Math.round((move[3]==='물리'?a[1]:a[3])*Number(move[4])*stab*itemPower(set.items,type,move[3])*abilityPower(set.abilities,type,move[3])),physical=Math.round(a[0]*a[2]),special=Math.round(a[0]*a[4]),speed=Math.floor(a[5]*(set.items==='구애스카프'?1.5:1)),bench=stats().slice(0,20),beat0=bench.filter(p=>speed>Number(master(p.name)[8])+20).length,beat32=bench.filter(p=>speed>Number(master(p.name)[8])+52).length;$('calcResult').innerHTML=`<h3>${esc(attacker.name)} → ${esc(defender.name)}</h3><p><b>${esc(move[0])}</b> · ${esc(type)} · ${esc(move[3])} · 자속 ×${stab} · 타입상성 ×${multiplier(type,defender.types)}</p><div class="calccards"><article><small>데미지</small><strong>${result.minPct}~${result.maxPct}%</strong><b>${esc(result.label)}</b></article><article><small>결정력 지수</small><strong>${power.toLocaleString()}</strong><b>공격 수치·위력·자속·도구·특성</b></article><article><small>내구력</small><strong>${physical.toLocaleString()} / ${special.toLocaleString()}</strong><b>물리 / 특수 · 무투자 대비 ${Math.round((physical/(zero[0]*zero[2])-1)*100)}% / ${Math.round((special/(zero[0]*zero[4])-1)*100)}%</b></article><article><small>스피드 ${speed}</small><strong>S0 ${beat0}종 / S32 ${beat32}종</strong><b>상위 ${bench.length}종보다 빠른 수</b></article></div><p class="leadnotice">86~100의 15개 난수 기준입니다. 명중률·급소·날씨·필드·랭크·벽·가변 위력 등은 제외합니다.</p>`}
function calcPair(){const attacker=row($('calcAtk').value.trim()),defender=row($('calcDef').value.trim());if(!attacker||!defender){toast('현재 챔피언스 목록에서 공격·방어 포켓몬을 선택해 주세요.');return null}return {attacker,defender}}
function runPowerSweep(){const pair=calcPair();if(!pair)return;const {attacker,defender}=pair,set=team().find(x=>x?.name===attacker.name)||makeSet(attacker),best=strongestStatMove(attacker,defender,set,D.master);if(!best)return toast('채용률 상위 4개 기술에서 계산 가능한 공격기를 찾지 못했습니다.');const lines=damageScenarioResults(attacker,defender,set,best.move,D.master).map(({label,calc})=>`<article><small>${esc(label)}</small><strong>${calc.result.minPct}~${calc.result.maxPct}%</strong><b>${esc(calc.result.label)} · ${calc.result.min}~${calc.result.max}</b></article>`).join('');$('calcResult').innerHTML=`<h3>${esc(attacker.name)} → ${esc(defender.name)} 결정력 일괄 계산</h3><p><b>${esc(best.move[0])}</b> · 채용률 ${best.rate}% · ${esc(best.calc.type)}/${esc(best.calc.category)} · 위력 ${best.move[4]} · 자속 ×${best.calc.stab} · 타입상성 ×${best.calc.typeMultiplier}</p><p>${esc(set.items||'도구 없음')} / ${esc(set.abilities||'특성 없음')} / ${esc(set.natures||'성격 없음')} / ${esc(evtext(set.evs))}</p><div class="calccards sweepcards">${lines}</div><p class="leadnotice">채용률 상위 4개 기술 중 대상에게 최대 피해를 주는 공격기를 사용합니다. 방어 성격은 무보정이며 조건부 효과·연속기 횟수·가변 위력 등은 제외합니다.</p>`}
function runSpeedCompare(){const pair=calcPair();if(!pair)return;const {attacker,defender}=pair,left=speedVariants(attacker,D.master),right=speedVariants(defender,D.master);if(!left||!right)return toast('현재 챔피언스 데이터로 스피드를 계산할 수 없습니다.');const lines=left.map((a,i)=>{const b=right[i],mark=a.value===b.value?'＝':a.value>b.value?'＞':'＜',winner=a.value===b.value?'동속':a.value>b.value?attacker.name:defender.name;return `<article><small>${esc(a.label)}</small><strong>${a.value} ${mark} ${b.value}</strong><b>${esc(attacker.name)} / ${esc(defender.name)} · ${esc(winner)}</b></article>`}).join('');$('calcResult').innerHTML=`<h3>${esc(attacker.name)} ↔ ${esc(defender.name)} 스피드 비교</h3><div class="calccards speedcards">${lines}</div><p class="leadnotice">최속은 S32+스피드 상승 성격, 준속은 S32 무보정 성격, 무보정은 S0입니다. 스카프는 해당 수치에 ×1.5 후 버림합니다.</p>`}
